function query(table, where) {
  const pairs = Object.entries(where || {}).map(([k, v]) => `${k}='${String(v)}'`);
  const clause = pairs.length ? ' WHERE ' + pairs.join(' AND ') : '';
  return `SELECT * FROM ${table}${clause}`;
}
module.exports = { query };

