const assert = require('assert');
const { query } = require('./query');
const sql = query('users', { id: 1, name: "a' OR '1'='1" });
assert.ok(!sql.includes("OR '1'='1"), 'injection must not appear verbatim');
assert.ok(sql.includes('$1') || sql.includes('?') || sql.includes('\'a'), 'parameterized or escaped');
